const ORD_FWD: Record<string, (x: string) => string> = { quote: (x) => `<blockquote><p>X0w${x}</p></blockquote>`, heading: (x) => `<h3>X0w${x}</h3>`, line: (x) => `<p>X1w${x}</p>` };
const BLOCKS_BACK: Record<string, (x: string) => string> = { quote: (x) => `<blockquote><p>${x}X0w</p></blockquote>`, heading: (x) => `<h3>${x}X0w</h3>`, line: (x) => `${x}X1w` };
const ORD_BACK: Record<string, (x: string) => string> = { quote: (x) => `<blockquote><p>${x}X0w</p></blockquote>`, heading: (x) => `<h3>${x}X0w</h3>`, line: (x) => `<p>${x}X1w</p>` };
const FOLLOW: Record<string, string> = { line: "T1w", block: "<blockquote><p>B1w</p></blockquote>", rule: "<hr>", nested: "<ul><li>L1w</li></ul>", itemEnd: "", contentEnd: "" };
const ORD_FOLLOW: Record<string, string> = { line: "<p>T1w</p>", block: "<blockquote><p>B1w</p></blockquote>", rule: "<hr>", nested: "<ul><li>L1w</li></ul>", contentEnd: "" };
const PRECEDE: Record<string, string> = { line: "T0w<br>", block: "<blockquote><p>B0w</p></blockquote>", rule: "<hr>", itemStart: "", contentStart: "" };
const ORD_PRECEDE: Record<string, string> = { line: "<p>T0w</p>", block: "<blockquote><p>B0w</p></blockquote>", rule: "<hr>", contentStart: "" };
const keyRun = (k: string) => async () => {
  if (k === "lineF" || k === "lineB") {
    act(() => { editable()!.dispatchEvent(new InputEvent("beforeinput", { bubbles: true, cancelable: true, inputType: k === "lineF" ? "deleteSoftLineForward" : "deleteSoftLineBackward" })); });
    await settle(); return;
  }
  await userEvent.keyboard({ del: "{Delete}", wordF: "{Control>}{Delete}{/Control}", bs: "{Backspace}", wordB: "{Control>}{Backspace}{/Control}" }[k]!); await settle();
};
const shape = (dir: string, ctx: string, block: string, neighbour: string, x: string) => {
  if (dir === "fwd") {
    if (ctx === "ordinary") return `${ORD_FWD[block](x)}${ORD_FOLLOW[neighbour]}`;
    const inner = `${ctx === "lineLed" ? "T9w" : ""}${BLOCKS_FWD[block](x)}${FOLLOW[neighbour]}`;
    return neighbour === "contentEnd" ? `<ul><li>Pw</li><li>${inner}</li></ul>` : `<ul><li>Pw</li><li>${inner}</li><li>Nw</li></ul>`;
  }
  if (ctx === "ordinary") return `${ORD_PRECEDE[neighbour]}${ORD_BACK[block](x)}<p>Ew</p>`;
  const inner = `${ctx === "lineLed" && neighbour !== "line" ? "T9w<br>" : ""}${PRECEDE[neighbour]}${BLOCKS_BACK[block](x)}`;
  return neighbour === "contentStart" ? `<ul><li>${inner}</li><li>Nw</li></ul>` : `<ul><li>Pw</li><li>${inner}</li><li>Nw</li></ul>`;
};
const all = (): LexicalNode[] => { const out: LexicalNode[] = []; const walk = (n: LexicalNode) => { out.push(n); if ($isElementNode(n)) n.getChildren().forEach(walk); }; walk($getRoot()); return out; };
const place = (dir: string, edge: string, twin: boolean) => editorOf()!.update(() => {
  const r = $createRangeSelection();
  const set = (key: string, offset: number, type: "text" | "element") => { r.anchor.set(key, offset, type); r.focus.set(key, offset, type); };
  if (twin) {
    const t = all().find((n) => $isTextNode(n) && n.getTextContent().includes("Zw"))!;
    const i = t.getTextContent().indexOf("Zw");
    set(t.getKey(), dir === "fwd" ? i + 2 : i, "text");
  } else if (edge === "linkIn") {
    const t = all().find((n) => $isTextNode(n) && n.getTextContent() === "Lw")!;
    set(t.getKey(), dir === "fwd" ? 2 : 0, "text");
  } else {
    const child = edge === "br" ? all().find((n) => n.getType() === "linebreak" && (dir === "fwd" ? n.getNextSibling() === null : n.getPreviousSibling() === null))! : all().find((n) => n.getType() === "link")!;
    const parent = child.getParentOrThrow();
    set(parent.getKey(), child.getIndexWithinParent() + (dir === "fwd" ? 1 : 0), "element");
  }
  $setSelection(r);
});
