describe("edge children write as their twins", () => {
  for (const [cell, expected] of EDGE_WRITES) {
    const [dir, edge, ctx, block, nb, k] = cell.split(" ");
    test(cell, async () => {
      const html = shape(dir, ctx, block, nb, EDGE[edge]);
      const onChange = await renderField(html);
      await click(editable());
      await act(async () => {
        place(dir, edge, false);
      });
      await settle();
      await keyRun(k)();
      const raw = lastHtml(onChange) === "" ? "NOOP" : sanitizeRichTextHtml(lastHtml(onChange));
      expect(raw).toBe(expected);
    }, 30_000);
  }
});
